def main() -> None:
    knowledge = ROOT / "fixtures" / "knowledge"
    evaluation = ROOT / "fixtures" / "eval"
    knowledge.mkdir(parents=True, exist_ok=True)
    evaluation.mkdir(parents=True, exist_ok=True)
    catalog = []
    for ident, title, product, version, symptom, diagnosis, steps, verification, boundary in DOCS:
        text = f"# {title}\n\n> 虚构演示资料：星河示例公司。仅用于 DeskPilot 测试，不是实际企业操作手册。\n\n"
        text += f"## 适用范围\n\n产品：{product}；适用版本：{version}。\n责任人：示例 IT 服务台；复核日期：2026-09-29。\n\n"
        text += f"## 用户现象\n\n{symptom}\n\n## 判断依据\n\n{diagnosis}\n\n## 处理步骤\n\n"
        text += "\n".join(f"{i}. {step}" for i, step in enumerate(steps, 1))
        text += f"\n\n## 验证与完成条件\n\n{verification}\n\n## 权限与风险边界\n\n{boundary}\n\n"
        text += "## 升级与知识维护\n\n若完成上述安全检查仍无法恢复，保留错误文字、版本和已尝试步骤创建工单。禁止把密码、令牌或完整业务文件写入工单。修复经验只形成待审核知识，审核通过后才能替换共享版本；旧版本应保留变更记录。\n"
        (knowledge / f"{ident}.md").write_text(text, encoding="utf-8")
        item = {"id": ident, "file": f"{ident}.md", "title": title, "product": product,
                "product_version": version, "owner": "示例 IT 服务台", "roles": ["employee", "it", "admin"],
                "cloud_allowed": True}
        if ident == "finance-share":
            item.update(allowed_users=["bob", "chen", "admin"], cloud_allowed=False)
        if ident == "it-vpn-gateway":
            item.update(roles=["it", "admin"], cloud_allowed=False)
        catalog.append(item)
    (knowledge / "catalog.json").write_text(json.dumps(catalog, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
    questions = []
    for family, split, category, user_id, behavior, expected, queries in CASES:
        for n, query in enumerate(queries, 1):
            questions.append({"id": f"{family}-{n}", "family": family, "split": split, "query": query,
                              "user_id": user_id, "expected_document_ids": expected,
                              "expected_behavior": behavior, "category": category})
    (evaluation / "questions.json").write_text(json.dumps(questions, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
    print(f"Wrote {len(catalog)} fictional documents and {len(questions)} labeled evaluation cases.")


if __name__ == "__main__":
    main()
